import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CD2m2Tvf.js";const u=JSON.parse('{"title":"AI & Machine Learning Integration Deep Dive","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-integration.md","filePath":"07-ai-integration.md"}'),o={name:"07-ai-integration.md"};function n(l,e,s,c,d,m){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-machine-learning-integration-deep-dive" tabindex="-1">AI &amp; Machine Learning Integration Deep Dive <a class="header-anchor" href="#ai-machine-learning-integration-deep-dive" aria-label="Permalink to &quot;AI &amp; Machine Learning Integration Deep Dive&quot;">​</a></h1><h2 id="architecture-hybrid-statistical-ml-pre-trained-llm" tabindex="-1">Architecture: Hybrid Statistical ML + Pre-trained LLM <a class="header-anchor" href="#architecture-hybrid-statistical-ml-pre-trained-llm" aria-label="Permalink to &quot;Architecture: Hybrid Statistical ML + Pre-trained LLM&quot;">​</a></h2><p>The AI subsystem consists of two complementary layers:</p><ol><li><strong>Statistical ML Engine (<code>ml/</code>)</strong>: Runs locally on incoming telemetry with sub-millisecond execution times.</li><li><strong>Pre-trained LLM API Integration (<code>ml/llm_engine.py</code>)</strong>: Queried on demand during active incident triage.</li></ol><hr><h2 id="statistical-ml-modules-11-total" tabindex="-1">Statistical ML Modules (11 Total) <a class="header-anchor" href="#statistical-ml-modules-11-total" aria-label="Permalink to &quot;Statistical ML Modules (11 Total)&quot;">​</a></h2><ol><li><code>latency_anomaly.py</code>: Calculates rolling exponential moving average (EMA) and standard deviation; flags z-score $&gt; 3.0$.</li><li><code>dependency_anomaly.py</code>: Constructs service call graph; detects unexpected RPC edge additions.</li><li><code>error_spike.py</code>: Detects sudden step changes in error rates using Poisson process estimation.</li><li><code>trace_anomaly.py</code>: Evaluates whole-trace structural graph complexity against historical baselines.</li><li><code>performance_regression.py</code>: Compares latency distributions between deployment versions using Kolmogorov-Smirnov tests.</li><li><code>slow_span_predictor.py</code>: Predicts whether an in-flight trace will breach SLO based on early span durations.</li><li><code>dynamic_sampling.py</code>: Dynamically increases sampling rate for services currently exhibiting anomalous behavior.</li><li><code>sampling_recommendation.py</code>: Recommends budget-optimized sampling percentages per endpoint.</li><li><code>semantic_search.py</code>: Generates vector embeddings for span error messages and exception stack traces.</li><li><code>root_cause.py</code>: Causal graph traversal prioritizing deepest downstream failed nodes.</li><li><code>llm_engine.py</code>: Structured prompt builder and output parser.</li></ol><hr><h2 id="llm-integration-prompt-guardrails" tabindex="-1">LLM Integration &amp; Prompt Guardrails <a class="header-anchor" href="#llm-integration-prompt-guardrails" aria-label="Permalink to &quot;LLM Integration &amp; Prompt Guardrails&quot;">​</a></h2><ul><li><strong>Model Used</strong>: External pre-trained LLM API (OpenAI GPT-4o-mini / Claude 3.5 Sonnet)</li><li><strong>Zero Custom ML Training</strong>: No custom neural networks were trained; pre-trained foundation models are accessed strictly via API.</li><li><strong>Prompt Guardrails</strong>: <ul><li>All span attributes pass through the PII redaction engine before prompt assembly.</li><li>System prompt enforces strict JSON schema output (<code>{ &quot;summary&quot;: str, &quot;root_cause&quot;: str, &quot;remediation&quot;: [str] }</code>).</li><li>Temperature set to <code>0.1</code> for maximum determinism.</li></ul></li></ul>',10)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
